const { spawn } = require('child_process');
const assert = require('assert');

// Spawn node with an inline runner that mimics run-all-tests.js execution of a failing suite
const codeToRun = \`
  const { spawn } = require('child_process');
  const path = require('path');
  const fs = require('fs');

  // Load run-all-tests module
  const runner = require('./tests/run-all-tests');

  // Create a temporary failing test
  const tempTestPath = 'tests/_temp_failing_test.js';
  fs.writeFileSync(tempTestPath, 'console.error(\"Intentional failure\"); process.exit(1);');

  // Overwrite TEST_SUITES to run only this failing test
  runner.TEST_SUITES.length = 0;
  runner.TEST_SUITES.push({
    id: 'FAIL-TEST',
    tier: 1,
    milestone: 'm6',
    name: 'Temporary Injected Failing Test',
    path: tempTestPath,
    minChecks: 1
  });

  // Intercept process.exit to clean up file and exit with runner's exit code
  const origExit = process.exit;
  process.exit = (code) => {
    try { fs.unlinkSync(tempTestPath); } catch (_) {}
    origExit(code);
  };

  runner.main().catch(err => {
    try { fs.unlinkSync(tempTestPath); } catch (_) {}
    origExit(1);
  });
\`;

const child = spawn('node', ['-e', codeToRun], { stdio: 'pipe' });
let out = '';
let err = '';
child.stdout.on('data', d => out += d);
child.stderr.on('data', d => err += d);

child.on('close', (code) => {
  console.log('Child output summary:');
  console.log(out.trim().split('\n').slice(-5).join('\n'));
  console.log('Exit code:', code);
  assert.strictEqual(code, 1, 'Master runner MUST exit with code 1 when a test fails');
  console.log('✔ Verification Succeeded: Master runner strictly exits with code 1 on suite failure');
});
